import sys

def solve():
    # Read input
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    N = int(input_data[0])
    S = input_data[1]

    MOD = 998244353

    # Function to compute nCr modulo MOD
    def nCr_mod(n, r, mod):
        if r < 0 or r > n:
            return 0
        num = 1
        den = 1
        for i in range(r):
            num = (num * (n - i)) % mod
            den = (den * (i + 1)) % mod
        return (num * pow(den, mod - 2, mod)) % mod

    # Function to compute Catalan number C_n = (1/(n+1)) * binom(2n, n)
    def catalan(n, mod):
        return nCr_mod(2 * n, n, mod) * pow(n + 1, mod - 2, mod) % mod

    # Check if S is a valid parenthesis sequence with W as '(' and B as ')'
    def is_valid_parenthesis(s, open_char, close_char):
        balance = 0
        for char in s:
            if char == open_char:
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Check both orientations
    if is_valid_parenthesis(S, 'W', 'B'):
        print(catalan(N, MOD))
    elif is_valid_parenthesis(S, 'B', 'W'):
        print(catalan(N, MOD))
    else:
        print(0)

