    solve()

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        even_dp = {}
        odd_dp = {}

        for x in nums:
            new_odd = {}
            new_even = {}

            if x <= limit:
                new_odd[x] = x

            for s, p in even_dp.items():
                ns = s + x
                np_val = p * x
                if np_val <= limit:
                    if ns not in new_odd or np_val > new_odd[ns]:
                        new_odd[ns] = np_val

            for s, p in odd_dp.items():
                ns = s - x
                np_val = p * x
                if np_val <= limit:
                    if ns not in new_even or np_val > new_even[ns]:
                        new_even[ns] = np_val

            for s, p in new_odd.items():
                if s not in odd_dp or p > odd_dp[s]:
                    odd_dp[s] = p

            for s, p in new_even.items():
                if s not in even_dp or p > even_dp[s]:
                    even_dp[s] = p

        ans = -1
        if k in odd_dp:
            ans = max(ans, odd_dp[k])
        if k in even_dp:
            ans = max(ans, even_dp[k])

        return ans

class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        P_nums = [0] * (n + 1)
        P_cost = [0] * (n + 1)
        for i in range(1, n + 1):
            P_nums[i] = P_nums[i - 1] + nums[i - 1]
            P_cost[i] = P_cost[i - 1] + cost[i - 1]

        INF = 10**18
        dp = [INF] * (n + 1)
        dp[0] = 0

        for m in range(1, n + 1):
            new_dp = [INF] * (n + 1)
            for j in range(m, n + 1):
                for l in range(m, j + 1):
                    prev = dp[l - 1]
                    if prev == INF:
                        continue
                    s_nums = P_nums[j] - P_nums[l - 1]
                    s_cost = P_cost[j] - P_cost[l - 1]
                    cost_last = (s_nums + k * m) * s_cost
                    total = prev + cost_last
                    if total < new_dp[j]:
                        new_dp[j] = total
            dp = new_dp

        return min(dp[1:])

