def solve():
    # Read all input from stdin
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        N = int(next(iterator))
        M = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(N + 1)]

    for _ in range(M):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * (N + 1)
    component_sizes = []

    for i in range(1, N + 1):
        if not visited[i]:
            # BFS or DFS to find component size
            stack = [i]
            visited[i] = True
            size = 0
            while stack:
                node = stack.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)
            component_sizes.append(size)

    # Calculate XOR sum of (size - 1)
    xor_sum = 0
    for size in component_sizes:
        xor_sum ^= (size - 1)

    if xor_sum > 0:
        print("Aoki")
    else:
        print("Takahashi")

