class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_up_to(n, s):
            if n == 0:
                return 0
            digits = list(map(int, str(n)))
            dp = defaultdict(int)
            dp[(True, False, 0, 0)] = 1

            for i, digit in enumerate(digits):
                new_dp = defaultdict(int)
                for (tight, started, current_sum, current_prod_mod), count in dp.items():
                    upper = digit if tight else 9
                    for d in range(0, upper + 1):
                        new_tight = tight and (d == upper)
                        if not started:
                            if d == 0:
                                new_started = False
                                new_sum = 0
                                new_prod_mod = 0
                            else:
                                new_started = True
                                new_sum = d
                                new_prod_mod = d % s
                        else:
                            new_started = True
                            new_sum = current_sum + d
                            new_prod_mod = (current_prod_mod * d) % s if d != 0 else 0

                        if new_sum > s:
                            continue
                        new_dp[(new_tight, new_started, new_sum, new_prod_mod)] += count
                dp = new_dp

            total = 0
            for (tight, started, current_sum, current_prod_mod), count in dp.items():
                if started and current_sum == s and current_prod_mod == 0:
                    total += count
            return total

        def count(n):
            if n == 0:
                return 0
            total = 0
            for s in range(1, 82):
                total += count_up_to(n, s)
            return total

        return count(r) - count(l - 1)

class TrieNode:
    __slots__ = ['count', 'children']
    def __init__(self):
        self.count = 0
        self.children = {}

class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if k > n:
            return [0] * n

        root = TrieNode()

        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]
                node.count += 1

        ans = []
        for i in range(n):
            word = words[i]
            node = root
            for char in word:
                node = node.children[char]
                node.count -= 1

            depth = 0
            current = root
            while True:
                found = False
                for child in current.children.values():
                    if child.count >= k:
                        current = child
                        depth += 1
                        found = True
                        break
                if not found:
                    break
            ans.append(depth)

            node = root
            for char in word:
                node = node.children[char]
                node.count += 1

        return ans

