class Fenw:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (self.n + 1)

    def update(self, index, delta):
        while index <= self.n:
            self.tree[index] += delta
            index += index & (-index)

    def query(self, index):
        s = 0
        while index > 0:
            s += self.tree[index]
            index -= index & (-index)
        return s

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        INF = n + 1

        pairs = []
        for a, b in conflictingPairs:
            L = min(a, b)
            R = max(a, b)
            pairs.append((L, R))

        min_R_for_L = [INF] * (n + 2)
        for L, R in pairs:
            if R < min_R_for_L[L]:
                min_R_for_L[L] = R

        min1 = [INF] * (n + 2)
        min2 = [INF] * (n + 2)
        for i in range(n, 0, -1):
            min1[i] = min1[i+1]
            min2[i] = min2[i+1]
            r = min_R_for_L[i]
            if r < min1[i]:
                min2[i] = min1[i]
                min1[i] = r
            elif r < min2[i]:
                min2[i] = r

        total_subarrays = n * (n + 1) // 2
        U = 0
        for i in range(1, n + 1):
            if min1[i] <= n:
                U += (n - min1[i] + 1)

        groups = {}
        for i in range(1, n + 1):
            if min1[i] != INF:
                val = max(0, min2[i] - min1[i])
                R_key = min1[i]
                if R_key not in groups:
                    groups[R_key] = []
                groups[R_key].append((i, val))

        for R_key in groups:
            lst = groups[R_key]
            lst.sort(key=lambda x: x[0])
            indices = [x[0] for x in lst]
            vals = [x[1] for x in lst]
            prefix = [0] * (len(vals) + 1)
            for idx in range(len(vals)):
                prefix[idx+1] = prefix[idx] + vals[idx]
            groups[R_key] = (indices, prefix)

        sorted_indices = sorted(range(1, n + 1), key=lambda i: min1[i], reverse=True)
        sorted_pairs = sorted(pairs, key=lambda x: x[1], reverse=True)

        fenw_sum = Fenw(n)
        fenw_count = Fenw(n)

        ptr = 0
        num_indices = len(sorted_indices)
        F_vals = [0] * len(pairs)

        for idx_p, (L_p, R_p) in enumerate(sorted_pairs):
            while ptr < num_indices and min1[sorted_indices[ptr]] > R_p:
                i = sorted_indices[ptr]
                fenw_sum.update(i, min1[i])
                fenw_count.update(i, 1)
                ptr += 1
            s = fenw_sum.query(L_p)
            c = fenw_count.query(L_p)
            F_vals[idx_p] = s - R_p * c

        only_p_list = []
        for idx_p, (L_p, R_p) in enumerate(pairs):
            F_val = F_vals[idx_p]
            G_val = 0
            if R_p in groups:
                indices_list, prefix_arr = groups[R_p]
                pos = bisect.bisect_right(indices_list, L_p)
                G_val = prefix_arr[pos]
            only_p_list.append(F_val + G_val)

        base_valid = total_subarrays - U
        ans = 0
        for only in only_p_list:
            candidate = base_valid + only
            if candidate > ans:
                ans = candidate

        return ans

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        res = ['a'] * L
        forced_val = [None] * L

        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if forced_val[pos] is not None and forced_val[pos] != str2[j]:
                        return ""
                    forced_val[pos] = str2[j]
                    res[pos] = str2[j]

        for i in range(n):
            if str1[i] == 'F':
                if res[i:i+m] == list(str2):
                    j = m - 1
                    while j >= 0:
                        pos = i + j
                        if forced_val[pos] is not None:
                            j -= 1
                            continue
                        if res[pos] != 'z':
                            res[pos] = chr(ord(res[pos]) + 1)
                            break
                        else:
                            res[pos] = 'a'
                            j -= 1
                    if j < 0:
                        return ""

        return "".join(res)

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
            if fact[i] > 10**16:
                fact[i] = 10**16 + 7

        odd_count = (n + 1) // 2
        even_count = n // 2

        total_odd_start = fact[odd_count] * fact[even_count]
        if n % 2 == 1:
            total_perm = total_odd_start
        else:
            total_perm = 2 * total_odd_start

        if k > total_perm:
            return []

        odds = [i for i in range(1, n + 1) if i % 2 == 1]
        evens = [i for i in range(1, n + 1) if i % 2 == 0]

        res = []

        if n % 2 == 1:
            start_parity = 'odd'
        else:
            if k <= total_odd_start:
                start_parity = 'odd'
            else:
                start_parity = 'even'
                k -= total_odd_start

        for i in range(n):
            if i % 2 == 0:
                if start_parity == 'odd':
                    required = 'odd'
                else:
                    required = 'even'
            else:
                if start_parity == 'odd':
                    required = 'even'
                else:
                    required = 'odd'

            if required == 'odd':
                available = odds
                rem_odds = len(odds) - 1
                rem_evens = len(evens)
                count_per_choice = fact[rem_odds] * fact[rem_evens]
            else:
                available = evens
                rem_odds = len(odds)
                rem_evens = len(evens) - 1
                count_per_choice = fact[rem_odds] * fact[rem_evens]

            idx = 0
            while idx < len(available):
                if k <= count_per_choice:
                    chosen = available.pop(idx)
                    res.append(chosen)
                    break
                else:
                    k -= count_per_choice
                    idx += 1

        return res

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        # Convert each point to its perimeter distance
        def get_perimeter(p):
            x, y = p
            if y == 0:
                return x
            elif x == side:
                return side + y
            elif y == side:
                return 2 * side + (side - x)
            else:  # x == 0
                return 3 * side + (side - y)

        # Create a list of perimeter distances
        perims = [get_perimeter(p) for p in points]
        perims.sort()

        n = len(perims)

        # Function to check if it's possible to choose k points with min distance >= d
        def feasible(d):
            # We need to select at least k points such that consecutive selected points are at least d apart
            count = 1
            last = perims[0]
            for i in range(1, n):
                if perims[i] - last >= d:
                    count += 1
                    last = perims[i]
                    if count >= k:
                        return True
            return False

        low = 0
        high = 2 * side
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

