class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        low = 0
        high = max(points) * m + 1

        def feasible(x):
            total_visits = 0
            for p in points:
                total_visits += (x + p - 1) // p
                if total_visits > m:
                    return False
            return total_visits <= m

        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if feasible(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1
        return ans

