class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        m = len(target)
        total_masks = 1 << m

        lcm_val = [1] * total_masks
        for mask in range(1, total_masks):
            l = 1
            for j in range(m):
                if mask & (1 << j):
                    l = math.lcm(l, target[j])
            lcm_val[mask] = l

        dp = [float('inf')] * total_masks
        dp[0] = 0

        for num in nums:
            new_dp = dp[:]
            for mask in range(total_masks):
                if dp[mask] == float('inf'):
                    continue
                for sub in range(1, total_masks):
                    if mask & sub:
                        continue
                    new_mask = mask | sub
                    L = lcm_val[sub]
                    r = num % L
                    cost = 0 if r == 0 else L - r
                    if dp[mask] + cost < new_dp[new_mask]:
                        new_dp[new_mask] = dp[mask] + cost
            dp = new_dp

        return dp[total_masks - 1]

