class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        l = 0
        current_cost = 0
        ans = 0
        from collections import deque
        dq = deque()

        for r in range(n):
            while dq and nums[dq[-1]] <= nums[r]:
                dq.pop()
            dq.append(r)

            if r > l:
                max_prev = nums[dq[0]]
                current_cost += max(0, max_prev - nums[r])

            while current_cost > k and l <= r:
                if dq[0] == l:
                    dq.popleft()
                if l > r:
                    break
                # Recompute cost for [l+1, r]
                current_cost = 0
                if l + 1 <= r:
                    m = nums[l+1]
                    for i in range(l+2, r+1):
                        if nums[i] < m:
                            current_cost += m - nums[i]
                        else:
                            m = nums[i]
                l += 1

