    crit_points = set()
    crit_points.add(1)
    crit_points.add(N)
    for (L, R) in intervals:
        if L - 1 >= 1:
            crit_points.add(L - 1)
        if R + 1 <= N:
            crit_points.add(R + 1)

    crit_list = sorted(crit_points)
    crit_set = set(crit_list)

    # Build graph: adjacency list
    graph = {x: [] for x in crit_list}

    # Direct jumps between critical points
    for x in crit_list:
        for i in range(A, B + 1):
            y = x + i
            if y > N:
                break
            if y in crit_set:
                graph[x].append(y)

    # Gap edges for gaps after each bad interval
    for i in range(M):
        L_i, R_i = intervals[i]
        start_gap = R_i + 1
        if start_gap > N:
            continue

        if i < M - 1:
            L_next, R_next = intervals[i+1]
            next_crit = L_next - 1
        else:
            next_crit = N

        # The gap of good squares is from start_gap to next_crit (inclusive)
        if next_crit < start_gap:
            continue

        gap_length = next_crit - start_gap + 1
        if gap_length >= B:
            if start_gap in crit_set and next_crit in crit_set:
                if next_crit not in graph[start_gap]:
                    graph[start_gap].append(next_crit)

    # Gap edge for the initial gap (from 1 to the first bad interval)
    if M > 0:
        L0, R0 = intervals[0]
        start_gap = 1
        next_crit = L0 - 1
        gap_length = next_crit - start_gap + 1
        if gap_length >= B and start_gap in crit_set and next_crit in crit_set:
            if next_crit not in graph[start_gap]:
                graph[start_gap].append(next_crit)

    # BFS from 1 to N
    queue = deque([1])
    visited = set([1])
    found = False
    while queue:
        x = queue.popleft()
        if x == N:
            found = True
            break
        for y in graph[x]:
