class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)
        sorted_intervals = []
        for i, (l, r, w) in enumerate(intervals):
            sorted_intervals.append((l, r, w, i))

        sorted_intervals.sort(key=lambda x: (x[1], x[0], x[3]))

        dp = [None] * 5
        dp[0] = (0, [], -1)
        for k in range(1, 5):
            dp[k] = (-1, [], -1)

        for l, r, w, idx in sorted_intervals:
            for k in range(4, 0, -1):
                prev_weight, prev_indices, prev_end = dp[k-1]
                if prev_end < l:
                    new_weight = prev_weight + w
                    new_indices = sorted(prev_indices + [idx])
                    current_weight, current_indices, current_end = dp[k]
                    if new_weight > current_weight:
                        dp[k] = (new_weight, new_indices, r)
                    elif new_weight == current_weight:
                        if new_indices < current_indices:
                            dp[k] = (new_weight, new_indices, r)

        best_weight = -1
        best_indices = []
        for k in range(1, 5):
            w, indices, _ = dp[k]
            if w > best_weight:
                best_weight = w
                best_indices = indices
            elif w == best_weight:
                if indices < best_indices:
                    best_indices = indices

        return best_indices

