class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        tree = [None] * (4 * n)

        def merge(left, right):
            if left is None:
                return right
            if right is None:
                return left
            total = left[3] + right[3]
            max_pre = max(left[1], left[3] + right[1])
            max_suf = max(right[2], right[3] + left[2])
            max_sub = max(left[0], right[0], left[2] + right[1])
            return (max_sub, max_pre, max_suf, total)

        def build(node, start, end):
            if start == end:
                val = nums[start]
                tree[node] = (val, val, val, val)
            else:
                mid = (start + end) // 2
                build(2 * node + 1, start, mid)
                build(2 * node + 2, mid + 1, end)
                tree[node] = merge(tree[2 * node + 1], tree[2 * node + 2])

        build(0, 0, n - 1)

        def query(node, start, end, l, r):
            if r < start or end < l:
                return None
            if l <= start and end <= r:
                return tree[node]
            mid = (start + end) // 2
            left_res = query(2 * node + 1, start, mid, l, r)
            right_res = query(2 * node + 2, mid + 1, end, l, r)
            if left_res is None:
                return right_res
            if right_res is None:
                return left_res
            return merge(left_res, right_res)

        original_max = tree[0][0]
        ans = original_max

        indices_map = defaultdict(list)
        for i, num in enumerate(nums):
            indices_map[num].append(i)

        for x, indices in indices_map.items():
            segments = []
            if indices[0] > 0:
                segments.append((0, indices[0] - 1))
            for i in range(1, len(indices)):
                l_seg = indices[i-1] + 1
                r_seg = indices[i] - 1
                if l_seg <= r_seg:
                    segments.append((l_seg, r_seg))
            if indices[-1] < n - 1:
                segments.append((indices[-1] + 1, n - 1))

            if not segments:
                continue

            seg_nodes = []
            for (l, r) in segments:
                node = query(0, 0, n - 1, l, r)
                seg_nodes.append(node)

            current_ans = -10**18
            for node in seg_nodes:
                if node[0] > current_ans:
                    current_ans = node[0]

            if seg_nodes:
                current = seg_nodes[0][2]
                if current > current_ans:
                    current_ans = current
                for i in range(1, len(seg_nodes)):
                    current = max(seg_nodes[i][2], current + seg_nodes[i][3])
                    if current > current_ans:
                        current_ans = current

            if current_ans > ans:
                ans = current_ans

        return ans

