class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # If no operations allowed, return the length of the longest contiguous segment
        if numOps == 0:
            max_run = 1
            current_run = 1
            for i in range(1, n):
                if s[i] == s[i-1]:
                    current_run += 1
                    max_run = max(max_run, current_run)
                else:
                    current_run = 1
            return max_run

        # Helper function to get the lengths of consecutive identical character segments
        def get_segments():
            segments = []
            if not s:
                return segments
            count = 1
            for i in range(1, n):
                if s[i] == s[i-1]:
                    count += 1
                else:
                    segments.append(count)
                    count = 1
            segments.append(count)
            return segments

        segments = get_segments()

        # Check function: returns True if it's possible to have max run length <= k with <= numOps flips
        def can_achieve(k):
            # If k is 0, it's impossible unless the string is empty, but n>=1 so k>=1
            if k == 0:
                return False
            flips_needed = 0
            for seg in segments:
                # For a segment of length 'seg', the number of flips needed to break it into segments of length <= k
                # is (seg - 1) // k
                flips_needed += (seg - 1) // k
                if flips_needed > numOps:
                    return False
            return flips_needed <= numOps

        # Binary search for the minimum k
        low, high = 1, n
        ans = n
        while low <= high:
            mid = (low + high) // 2
            if can_achieve(mid):
                ans = mid
                high = mid - 1
            else:
                low = mid + 1
        return ans

class Solution:
    def subsequencesWithMiddleMode(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        n = len(nums)

        def nCr(n, r):
            if r < 0 or r > n:
                return 0
            if r == 0 or r == n:
                return 1
            if r > n // 2:
                r = n - r
            res = 1
            for i in range(r):
                res = res * (n - i) // (i + 1)
            return res

        ans = 0
        for i in range(2, n - 2):
            mid = nums[i]
            left_part = nums[0:i]
            right_part = nums[i+1:n]

            from collections import Counter
            freqL = Counter(left_part)
            freqR = Counter(right_part)

            midL = freqL.get(mid, 0)
            midR = freqR.get(mid, 0)
            nonMidL = i - midL
            nonMidR = len(right_part) - midR

            total_same_left = 0
            for w, count in freqL.items():
                if w == mid:
                    continue
                if count >= 2:
                    total_same_left += nCr(count, 2)

            total_same_right = 0
            for w, count in freqR.items():
                if w == mid:
                    continue
                if count >= 2:
                    total_same_right += nCr(count, 2)

            total_ways = 0
            for a in range(0, 3):
                for b in range(0, 3):
                    if a + b == 0:
                        continue
                    f = 1 + a + b
                    w_mid_left = nCr(midL, a)
                    w_mid_right = nCr(midR, b)

                    if a + b >= 2:
                        w_left_non = nCr(nonMidL, 2 - a) if (2 - a) >= 0 else 0
                        w_right_non = nCr(nonMidR, 2 - b) if (2 - b) >= 0 else 0
                        total_ways += w_mid_left * w_mid_right * w_left_non * w_right_non
                    else:
                        if a == 0 and b == 1:
                            ways = 0
                            for z_val, z_count in freqR.items():
                                if z_val == mid:
                                    continue
                                left_non_z = nonMidL - freqL.get(z_val, 0)
                                if left_non_z < 2:
                                    term = 0
                                else:
                                    same_for_z = nCr(freqL.get(z_val, 0), 2)
                                    term = nCr(left_non_z, 2) - (total_same_left - same_for_z)
                                ways += z_count * term
                            total_ways += w_mid_left * w_mid_right * ways
                        elif a == 1 and b == 0:
                            ways = 0
                            for l_val, l_count in freqL.items():
                                if l_val == mid:
                                    continue
                                right_non_l = nonMidR - freqR.get(l_val, 0)
                                if right_non_l < 2:
                                    term = 0
                                else:
                                    same_for_l = nCr(freqR.get(l_val, 0), 2)
                                    term = nCr(right_non_l, 2) - (total_same_right - same_for_l)
                                ways += l_count * term
                            total_ways += w_mid_left * w_mid_right * ways

            ans = (ans + total_ways) % mod

        return ans

