class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        num_set = set(nums)

        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each number in nums, check its multiples up to threshold
        for i, x in enumerate(nums):
            # Start from k=2 because k=1 gives the same number
            k = 2
            while x * k <= threshold:
                y = x * k
                if y in num_set:
                    # Find the index of y in nums
                    # Since we need to union the current index i with the index of y
                    # We can precompute a mapping from value to index for O(1) access
                    # But note: we don't have a direct mapping here. 
                    # Instead, we can store a dictionary mapping value to index.
                    # Let's create that mapping outside the loop.
                    pass
                k += 1

        # To avoid searching for index of y, we create a value to index mapping
        val_to_index = {val: i for i, val in enumerate(nums)}

        # Now re-iterate to do unions
        for i, x in enumerate(nums):
            k = 2
            while x * k <= threshold:
                y = x * k
                if y in val_to_index:
                    j = val_to_index[y]
                    union(i, j)
                k += 1

        # Count the number of connected components
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1
        return components
